import{_ as s,o as n,c as e,a4 as t}from"./chunks/framework.vNSRaLQv.js";const b=JSON.parse('{"title":"小模型号池驱动的数据清洗技术","description":"","frontmatter":{"title":"小模型号池驱动的数据清洗技术","date":"2026-07-05T00:00:00.000Z"},"headers":[],"relativePath":"posts/小模型号池驱动的数据清洗技术.md","filePath":"posts/小模型号池驱动的数据清洗技术.md"}'),i={name:"posts/小模型号池驱动的数据清洗技术.md"};function l(p,a,r,o,d,h){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="小模型号池驱动的数据清洗技术" tabindex="-1">小模型号池驱动的数据清洗技术 <a class="header-anchor" href="#小模型号池驱动的数据清洗技术" aria-label="Permalink to &quot;小模型号池驱动的数据清洗技术&quot;">​</a></h1><h2 id="核心思路" tabindex="-1">核心思路 <a class="header-anchor" href="#核心思路" aria-label="Permalink to &quot;核心思路&quot;">​</a></h2><ul><li>不用昂贵的大模型做数据清洗，改用多个廉价小模型 API 组成资源池</li><li>轮询调度 + 多路并发，榨干所有可用 API key 的吞吐量</li><li>分层调度：父代理派子代理，子代理直调 API</li></ul><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>作用</th></tr></thead><tbody><tr><td>CPA（Cloud Proxy API）</td><td>API 网关，多 provider 轮询 + 冷却 fallback</td></tr><tr><td>opencode Task 工具</td><td>父代理派生子代理，天然支持并发</td></tr><tr><td>子代理（Sub-agent）</td><td>每个处理 10 个 job，直接调 CPA</td></tr><tr><td>PROMPT.md</td><td>任务规则文件，子代理自我读取</td></tr></tbody></table><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to &quot;架构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>CPA 配置</span></span>
<span class="line"><span>  routing.strategy: round-robin  # 轮询分配</span></span>
<span class="line"><span>  session-affinity: false        # 关粘性会话</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可用 provider 池（已启用）：</span></span>
<span class="line"><span>  agnes-2.0-flash</span></span>
<span class="line"><span>  小水管user (deepseek-v4-flash 等)</span></span>
<span class="line"><span>  小水管claude (deepseek-v4-flash)</span></span>
<span class="line"><span>  yjjhwjw (agnes-2.0-flash)</span></span>
<span class="line"><span>  SenseNova (deepseek-v4-flash)</span></span></code></pre></div><h2 id="工作流程" tabindex="-1">工作流程 <a class="header-anchor" href="#工作流程" aria-label="Permalink to &quot;工作流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>pending/ 按 10 个一分 → batch_001 ~ batch_422</span></span>
<span class="line"><span>                    ↓</span></span>
<span class="line"><span>父代理 A（前向 batch_001→211）  父代理 B（反向 batch_422→212）</span></span>
<span class="line"><span>    ↓ 循环派生子代理                  ↓ 循环派生子代理</span></span>
<span class="line"><span>10 个子代理并行处理 10 个 batch    10 个子代理并行处理 10 个 batch</span></span>
<span class="line"><span>    ↓ 每子代理调 CPA                   ↓ 每子代理调 CPA</span></span>
<span class="line"><span>CPA 轮询分配到不同 provider      CPA 轮询分配到不同 provider</span></span>
<span class="line"><span>    ↓                                  ↓</span></span>
<span class="line"><span>写 .decision.json 到原文件夹      写 .decision.json 到原文件夹</span></span></code></pre></div><h2 id="关键设计" tabindex="-1">关键设计 <a class="header-anchor" href="#关键设计" aria-label="Permalink to &quot;关键设计&quot;">​</a></h2><ul><li><strong>每 10 个 job 一个文件夹</strong>：最小工作单元，子代理零冲突</li><li><strong>两路对进</strong>：前向 + 反向，避免文件锁竞争</li><li><strong>自我发现</strong>：子代理只需读 PROMPT.md，自动知道做什么</li><li><strong>CPA 轮询</strong>：多个 provider 自动负载均衡，429 自动冷却换下一个</li><li><strong>不移动文件</strong>：原地写 .decision.json，零搬运开销</li></ul><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>大量数据需要逐条做 AI 判断（切分、分类、标注等）</li><li>多个廉价 API 可用但单个有限速</li><li>需要高并发吞吐但预算有限</li></ul><h2 id="实际效果" tabindex="-1">实际效果 <a class="header-anchor" href="#实际效果" aria-label="Permalink to &quot;实际效果&quot;">​</a></h2><ul><li>4355 条 job，分批 422 个文件夹</li><li>20 个子代理并发（2 个父代理 × 10 个子代理）</li><li>预计 2~3 小时完成全部清洗</li></ul>`,15)])])}const u=s(i,[["render",l]]);export{b as __pageData,u as default};
